mapper.select:
select id, user_id, follow_user_id, create_time from user_follow

order by ${query.orderBy}
limit #{query.simplePage.start}, #{query.simplePage.end}

select f.follow_user_id as other_user_id, u.nick_name, u.avatar, u.personal_sign, u.total_fans, f.create_time from user_follow f left join user_info u on u.user_id = f.follow_user_id where f.user_id = #{query.userId}
and u.nick_name like concat('%', #{query.nickNameFuzzy}, '%')
order by f.create_time desc limit #{query.simplePage.start}, #{query.simplePage.end}

select f.user_id as other_user_id, u.nick_name, u.avatar, u.personal_sign, u.total_fans, f.create_time from user_follow f left join user_info u on u.user_id = f.user_id where f.follow_user_id = #{query.followUserId}
and u.nick_name like concat('%', #{query.nickNameFuzzy}, '%')
order by f.create_time desc limit #{query.simplePage.start}, #{query.simplePage.end}
